/**
 * GENERATED by `npm run guide:shots -- --manual`. Do not edit by hand.
 *
 * One entry per manual screenshot that has actually been captured: its pixel size and the box
 * around the highlighted control, measured on the live page in percent of the image. A shot
 * named in the manual but missing here is simply not drawn, so the guide never shows a broken
 * image while a capture is pending.
 */
export type CapturedShot = {
  /** Served from `public/`. The capture decides the format, so the guide reads it from here. */
  src: string;
  width: number;
  height: number;
  hotspot?: { x: number; y: number; w: number; h: number };
};

export const MANUAL_SHOTS: Record<string, CapturedShot> = {};
